"""Typed access to store tables."""

from __future__ import annotations

from collections.abc import Callable
from typing import Generic, TypeVar

T = TypeVar("T")


class Repository(Generic[T]):
    def __init__(self, store, name: str) -> None:
        self._store = store
        self._name = name

    def add(self, factory: Callable[[int], T]) -> T:
        new_id = self._store.next_id(self._name)
        obj = factory(new_id)
        self._store.table(self._name)[new_id] = obj
        return obj

    def get(self, obj_id: int) -> T | None:
        return self._store.table(self._name).get(obj_id)

    def all(self) -> list[T]:
        return sorted(self._store.table(self._name).values(), key=lambda obj: obj.id)

    def save(self, obj: T) -> T:
        self._store.table(self._name)[obj.id] = obj
        return obj


def get_repo(store, name: str) -> Repository:
    return Repository(store, name)

import importlib

from taskapp import schemas
from taskapp.registry import ROUTE_REGISTRY


def test_every_route_schema_is_exported():
    assert [route.schema for route in ROUTE_REGISTRY if route.schema not in schemas.__all__] == []


def test_every_route_handler_resolves():
    for route in ROUTE_REGISTRY:
        module_name, func_name = route.handler.split(":")
        assert hasattr(importlib.import_module(module_name), func_name), route.handler


def test_routes_are_unique():
    keys = [(route.method, route.path) for route in ROUTE_REGISTRY]
    assert len(keys) == len(set(keys))

